use std::process::{Command, Output};
use std::io;

/// Executes an arbitrary system command and returns the output
/// 
/// # Arguments
/// * `command` - The command to execute
/// * `args` - Arguments to pass to the command
///
/// # Returns
/// * `Result<Output, io::Error>` - The command output or an error
pub fn execute_command(command: &str, args: &[&str]) -> Result<Output, io::Error> {
    Command::new(command)
        .args(args)
        .output()
}

/// Executes a shell command string and returns the output
///
/// # Arguments
/// * `cmd` - The full command string to execute
///
/// # Returns
/// * `Result<Output, io::Error>` - The command output or an error
pub fn execute_shell_command(cmd: &str) -> Result<Output, io::Error> {
    #[cfg(target_os = "windows")]
    {
        Command::new("cmd")
            .args(&["/C", cmd])
            .output()
    }

    #[cfg(not(target_os = "windows"))]
    {
        Command::new("sh")
            .args(&["-c", cmd])
            .output()
    }
}

/// Executes a command and returns stdout as a string
///
/// # Arguments
/// * `command` - The command to execute
/// * `args` - Arguments to pass to the command
///
/// # Returns
/// * `Result<String, Box<dyn std::error::Error>>` - The stdout output or an error
pub fn execute_command_to_string(command: &str, args: &[&str]) -> Result<String, Box<dyn std::error::Error>> {
    let output = execute_command(command, args)?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Err(format!("Command failed: {}", stderr).into());
    }

    Ok(String::from_utf8(output.stdout)?)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_execute_command() {
        #[cfg(target_os = "windows")]
        let result = execute_command("cmd", &["/C", "echo test"]);

        #[cfg(not(target_os = "windows"))]
        let result = execute_command("echo", &["test"]);

        assert!(result.is_ok());
        let output = result.unwrap();
        assert!(output.status.success());
    }

    #[test]
    fn test_execute_shell_command() {
        let result = execute_shell_command("echo test");
        assert!(result.is_ok());
        let output = result.unwrap();
        assert!(output.status.success());
    }
}

